package eval

func lootDistributionSuite() Suite {
	base := currencyAndTradeSuite()
	return Suite{ID: "058-loot-distribution", Name: "Campaign Play 058: Loot Distribution", Tests: append(base.Tests,
		playTest("play-loot-create-unauthenticated", "Reject unauthenticated loot creation", "POST", "/v1/play/campaigns/play-2/loot", map[string]any{"loot_id": "loot-1", "item_id": "healing-potion", "quantity": 1}, nil, 401, nil),
		playTest("play-loot-create-player-forbidden", "Only the DM can create loot", "POST", "/v1/play/campaigns/play-2/loot", map[string]any{"loot_id": "loot-1", "item_id": "healing-potion", "quantity": 1}, map[string]string{"Authorization": playerAAuth}, 403, nil),
		playTest("play-loot-create-unknown-item", "Loot requires a known inventory item", "POST", "/v1/play/campaigns/play-2/loot", map[string]any{"loot_id": "loot-bad", "item_id": "longsword", "quantity": 1}, map[string]string{"Authorization": dmAuth}, 400, nil),
		playTest("play-loot-create-invalid-quantity", "Loot requires positive quantity", "POST", "/v1/play/campaigns/play-2/loot", map[string]any{"loot_id": "loot-bad", "item_id": "healing-potion", "quantity": 0}, map[string]string{"Authorization": dmAuth}, 400, nil),
		playTest("play-loot-create", "DM opens a loot record", "POST", "/v1/play/campaigns/play-2/loot", map[string]any{"loot_id": "loot-1", "item_id": "healing-potion", "quantity": 1}, map[string]string{"Authorization": dmAuth}, 201, map[string]any{"loot_id": "loot-1", "item_id": "healing-potion", "quantity": 1, "status": "open"}),
		playTest("play-loot-create-duplicate", "Duplicate loot IDs conflict", "POST", "/v1/play/campaigns/play-2/loot", map[string]any{"loot_id": "loot-1", "item_id": "healing-potion", "quantity": 1}, map[string]string{"Authorization": dmAuth}, 409, nil),
		playTest("play-loot-vote-dm-forbidden", "DM cannot cast a player loot vote", "POST", "/v1/play/campaigns/play-2/loot/loot-1/votes", map[string]any{"recipient_character_id": "play-char-b"}, map[string]string{"Authorization": dmAuth}, 403, nil),
		playTest("play-loot-vote-unknown-recipient", "Loot vote recipient must be a campaign character", "POST", "/v1/play/campaigns/play-2/loot/loot-1/votes", map[string]any{"recipient_character_id": "play-char-z"}, map[string]string{"Authorization": playerAAuth}, 400, nil),
		playTest("play-loot-vote-player-a", "Player A votes for the recipient", "POST", "/v1/play/campaigns/play-2/loot/loot-1/votes", map[string]any{"recipient_character_id": "play-char-b"}, map[string]string{"Authorization": playerAAuth}, 201, map[string]any{"loot_id": "loot-1", "voter": "player-a", "recipient_character_id": "play-char-b", "votes_for_recipient": 1}),
		playTest("play-loot-vote-duplicate", "A player vote is immutable", "POST", "/v1/play/campaigns/play-2/loot/loot-1/votes", map[string]any{"recipient_character_id": "play-char-w"}, map[string]string{"Authorization": playerAAuth}, 409, nil),
		playTest("play-loot-vote-player-b", "Player B votes for the same recipient", "POST", "/v1/play/campaigns/play-2/loot/loot-1/votes", map[string]any{"recipient_character_id": "play-char-b"}, map[string]string{"Authorization": playerBAuth}, 201, map[string]any{"loot_id": "loot-1", "voter": "player-b", "recipient_character_id": "play-char-b", "votes_for_recipient": 2}),
		playTest("play-loot-read-open", "Members can read the immutable open loot record", "GET", "/v1/play/campaigns/play-2/loot/loot-1", nil, map[string]string{"Authorization": playerAAuth}, 200, map[string]any{"loot_id": "loot-1", "item_id": "healing-potion", "quantity": 1, "status": "open", "votes": map[string]any{"play-char-b": 2}}),
		playTest("play-loot-create-tie", "DM opens separate loot for tie handling", "POST", "/v1/play/campaigns/play-2/loot", map[string]any{"loot_id": "loot-tie", "item_id": "torch", "quantity": 1}, map[string]string{"Authorization": dmAuth}, 201, map[string]any{"loot_id": "loot-tie", "item_id": "torch", "quantity": 1, "status": "open"}),
		playTest("play-loot-tie-vote-a", "Player A votes for one tie recipient", "POST", "/v1/play/campaigns/play-2/loot/loot-tie/votes", map[string]any{"recipient_character_id": "play-char-w"}, map[string]string{"Authorization": playerAAuth}, 201, map[string]any{"loot_id": "loot-tie", "voter": "player-a", "recipient_character_id": "play-char-w", "votes_for_recipient": 1}),
		playTest("play-loot-tie-vote-b", "Player B votes for another tie recipient", "POST", "/v1/play/campaigns/play-2/loot/loot-tie/votes", map[string]any{"recipient_character_id": "play-char-b"}, map[string]string{"Authorization": playerBAuth}, 201, map[string]any{"loot_id": "loot-tie", "voter": "player-b", "recipient_character_id": "play-char-b", "votes_for_recipient": 1}),
		playTest("play-loot-assign-tie-conflict", "Tied loot cannot be assigned", "POST", "/v1/play/campaigns/play-2/loot/loot-tie/assign", nil, map[string]string{"Authorization": dmAuth}, 409, nil),
		playTest("play-loot-assign-player-forbidden", "Only the DM can assign voted loot", "POST", "/v1/play/campaigns/play-2/loot/loot-1/assign", nil, map[string]string{"Authorization": playerAAuth}, 403, nil),
		playTest("play-loot-assign", "DM assigns loot to the unambiguous vote winner", "POST", "/v1/play/campaigns/play-2/loot/loot-1/assign", nil, map[string]string{"Authorization": dmAuth}, 200, map[string]any{"loot_id": "loot-1", "recipient_character_id": "play-char-b", "item_id": "healing-potion", "quantity": 1, "votes": 2, "status": "assigned"}),
		playTest("play-loot-assign-duplicate", "Duplicate loot assignment conflicts", "POST", "/v1/play/campaigns/play-2/loot/loot-1/assign", nil, map[string]string{"Authorization": dmAuth}, 409, nil),
		playTest("play-loot-read-assigned", "Members can read assigned loot status", "GET", "/v1/play/campaigns/play-2/loot/loot-1", nil, map[string]string{"Authorization": playerBAuth}, 200, map[string]any{"loot_id": "loot-1", "recipient_character_id": "play-char-b", "item_id": "healing-potion", "quantity": 1, "status": "assigned", "votes": map[string]any{"play-char-b": 2}}),
		playTest("play-loot-recipient-inventory", "Assigned loot appears in recipient inventory once", "GET", "/v1/play/campaigns/play-2/characters/play-char-b/inventory/items", nil, map[string]string{"Authorization": playerAAuth}, 200, map[string]any{"character_id": "play-char-b", "items": []any{map[string]any{"item_id": "healing-potion", "quantity": 1}}}),
	)}
}
